def solve6(g):
    H,W=len(g),len(g[0])
    bgc=Counter(x for r in g for x in r).most_common(1)[0][0]
    cs=[(c,set(s)) for c,s in lib.components(g,bgc,diag=True)]
    L=max(cs,key=lambda t:(lscore(t[1]),len(t[1]))); Ls=L[1]; Lc=L[0]
    ends=[p for p in Ls if sum((abs(p[0]-y)<=1 and abs(p[1]-x)<=1) for y,x in Ls if (y,x)!=p)==1]
    others=[t for t in cs if t!=L]
    # touching exception
    for c,s in others:
        if any(abs(y1-y2)+abs(x1-x2)==1 for y1,x1 in s for y2,x2 in Ls):
            return [[Lc if (y,x) in s else g[y][x] for x in range(W)] for y in range(H)]
    def dL(s): return min(abs(y1-y2)+abs(x1-x2) for y1,x1 in s for y2,x2 in Ls)
    def dE(s): return min(min(abs(y-ey)+abs(x-ex) for y,x in s) for ey,ex in ends)
    groups={}
    for c,s in others: groups.setdefault(len(s),[]).append((c,s))
    cands=[]
    for n,mem in groups.items():
        if len(mem)<2: continue
        far=max(mem,key=lambda t:(dL(t[1]),dE(t[1])))
        cands.append((dL(far[1]),dE(far[1]),far))
    _,_,(fc,fs)=min(cands,key=lambda t:(t[0],t[1]))
    return [[Lc if (y,x) in fs else g[y][x] for x in range(W)] for y in range(H)]
